[{"order":1,"type":"heading","text":"PHP Basic Syntax and Data Types"},{"order":2,"type":"subheading","text":"Introduction"},{"order":3,"type":"paragraph","text":"This tutorial covers the fundamental syntax and data types in PHP, including variables, operators, and control structures. Understanding these concepts is crucial for building any PHP application."},{"order":4,"type":"subheading","text":"Basic Syntax"},{"order":5,"type":"paragraph","text":"PHP code is embedded within HTML using the '<?php' and '?>' tags. All PHP statements end with a semicolon (;)."},{"order":6,"type":"code","text":"<?php
  echo "Hello, World!"; // This is a comment
?>"},{"order":7,"type":"paragraph","text":"Comments can be single-line (//) or multi-line (/* ... */)."},{"order":8,"type":"subheading","text":"Variables"},{"order":9,"type":"paragraph","text":"Variables in PHP are declared using the '$' symbol. They are case-sensitive and do not require explicit type declaration."},{"order":10,"type":"code","text":"<?php
  $name = "John";
  $age = 30;
  echo "Name: " . $name . ", Age: " . $age;
?>"},{"order":11,"type":"subheading","text":"Data Types"},{"order":12,"type":"paragraph","text":"PHP supports several data types:"},{"order":13,"type":"bullet_point","text":"String: Sequence of characters (e.g., "Hello")"},{"order":14,"type":"bullet_point","text":"Integer: Whole numbers (e.g., 10, -5)"},{"order":15,"type":"bullet_point","text":"Float: Floating-point numbers (e.g., 3.14, -2.5)"},{"order":16,"type":"bullet_point","text":"Boolean: True or false"},{"order":17,"type":"bullet_point","text":"Array: Collection of values"},{"order":18,"type":"bullet_point","text":"Object: Instance of a class"},{"order":19,"type":"bullet_point","text":"NULL: Represents the absence of a value"},{"order":20,"type":"code","text":"<?php
  $string = "Hello";
  $integer = 10;
  $float = 3.14;
  $boolean = true;
  $array = array(1, 2, 3);
  $nullValue = NULL;

  var_dump($string, $integer, $float, $boolean, $array, $nullValue); // Display data types and values
?>"},{"order":21,"type":"subheading","text":"Operators"},{"order":22,"type":"paragraph","text":"PHP provides various operators for performing operations on variables and values:"},{"order":23,"type":"bullet_point","text":"Arithmetic operators: +, -, *, /, % (modulus)"},{"order":24,"type":"bullet_point","text":"Assignment operators: =, +=, -=, *=, /="},{"order":25,"type":"bullet_point","text":"Comparison operators: == (equal), != (not equal), >, <, >=, <=, === (identical), !== (not identical)"},{"order":26,"type":"bullet_point","text":"Logical operators: && (and), || (or), ! (not)"},{"order":27,"type":"bullet_point","text":"String operators: . (concatenation)"},{"order":28,"type":"code","text":"<?php
  $x = 10;
  $y = 5;

  echo "Sum: " . ($x + $y) . "<br>";
  echo "Product: " . ($x * $y) . "<br>";

  if ($x > $y && $x != 0) {
    echo "x is greater than y and not zero.";
  }
?>"},{"order":29,"type":"subheading","text":"Control Structures"},{"order":30,"type":"paragraph","text":"Control structures allow you to control the flow of execution in your code."},{"order":31,"type":"bullet_point","text":"if, elseif, else: Conditional statements"},{"order":32,"type":"bullet_point","text":"switch: Multi-way branching"},{"order":33,"type":"bullet_point","text":"while: Loop that executes as long as a condition is true"},{"order":34,"type":"bullet_point","text":"do...while: Loop that executes at least once"},{"order":35,"type":"bullet_point","text":"for: Loop with initialization, condition, and increment/decrement"},{"order":36,"type":"bullet_point","text":"foreach: Loop for iterating over arrays"},{"order":37,"type":"code","text":"<?php
  $age = 20;

  if ($age >= 18) {
    echo "You are an adult.<br>";
  } else {
    echo "You are a minor.<br>";
  }

  $colors = array("red", "green", "blue");
  foreach ($colors as $color) {
    echo $color . "<br>";
  }

  for ($i = 0; $i < 5; $i++) {
    echo "Number: " . $i . "<br>";
  }
?>"},{"order":38,"type":"subheading","text":"Conclusion"},{"order":39,"type":"paragraph","text":"This tutorial covered the basic syntax, data types, variables, operators, and control structures in PHP. Mastering these fundamentals is essential for developing more complex PHP applications. Practice these concepts to solidify your understanding."}]
